"use client";
import { useState } from "react";
type Question = {question:string;options:string[];answer:number;explanation:string};
export default function Quiz({test}:{test:{title:string;questions:Question[]}}) {
 const [answers,setAnswers]=useState<Record<number,number>>({});
 const [submitted,setSubmitted]=useState(false);
 const score=test.questions.reduce((n,q,i)=>n+(answers[i]===q.answer?1:0),0);
 return <div className="space-y-5">{test.questions.map((q,i)=><section key={q.question} className="card p-5"><p className="text-xs text-violet-200">QUESTION {i+1} OF {test.questions.length}</p><h2 className="mt-3 font-semibold leading-7">{q.question}</h2><div className="mt-4 grid gap-2">{q.options.map((option,j)=><label key={option} className={`flex cursor-pointer items-center gap-3 rounded-xl border p-3 text-sm ${answers[i]===j?"border-violet-300 bg-violet-300/10":"border-white/10"}`}><input type="radio" name={`q${i}`} disabled={submitted} checked={answers[i]===j} onChange={()=>setAnswers(a=>({...a,[i]:j}))}/>{option}</label>)}</div>{submitted&&<p className="mt-3 text-sm leading-6 text-gray-300">Correct answer: {q.options[q.answer]}. {q.explanation}</p>}</section>)}<button disabled={submitted||Object.keys(answers).length!==test.questions.length} onClick={()=>setSubmitted(true)} className="rounded-xl bg-violet-300 px-5 py-3 font-semibold text-black disabled:opacity-40">{submitted?"Test submitted":"Submit answers"}</button>{submitted&&<div className="card p-6"><p className="text-sm text-gray-400">YOUR RESULT</p><p className="mt-2 text-3xl font-semibold">{score} / {test.questions.length}</p><p className="mt-2 text-sm text-gray-400">{Math.round(score/test.questions.length*100)}% correct. Review the explanations above to learn from each answer.</p><button onClick={()=>{setAnswers({});setSubmitted(false)}} className="mt-4 text-sm text-violet-200">Try again</button></div>}</div>;
}
